General structure:
if(s==t)
a = s;
a = a – t;

bne s0, t0, L1
add a0, s0, zero
L1: sub a0, a0, t0

if(s!=t)
    a = s;
else
    a = s + t;
a = a – t;

beq s0, t0, else
add a0, s0, zero
j L1
else:
add a0, s0, t0
L1:
sub t0, a0, s1

int sum = 0;
for(int i=1; i < 10; i++)
    sum = sum + i;

addi s1, zero, 0 # sum = 0
addi s0, zero, 1 # i = 1
addi t0, zero, 10 # t0 = 10
for:
bge s0, t0, done # i >= 10?
add s1, s1, s0 # sum = sum + i
addi s0, s0, 1 # i = i + 1
j for # repeat loop
done:

int main(){
    int y;
    y = sum(3,8);
    ...
}
int sum(int x, int y){
    return x + y;
}

main:
    addi $a0, $0, 3 <- $a0, $a1 as arguments
    addi $a1, $0, 8
    jal sum
    add $s0, $v0, $0
    ...
sum:
    add $v0, $a0, $a1 <- Save return value in $v0
    jr $ra

void swap(int* x, int* y){
    int temp;
    temp = *x;
    *x = *y;
    *y = temp;
}

li $a0, 0x00000014
li $a1, 0x00000010
jal swap
[...]
swap:
lw $t0, 0($a0)
lw $t1, 0($a1)
sw $t0, 0($a1)
sw $t1, 0($a0)
jr $ra
